export const NMTRAN_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/nmtran-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getNmtranStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(NMTRAN_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
